function panel(title,description,actions){paused=true;keys.clear();$('serviceTitle').textContent=title;$('serviceDescription').textContent=description;$('serviceBalance').textContent='$'+cityMoney+' · Energy '+cityEnergy+'/100 · Snacks '+cityInventory.snack+' · Water '+cityInventory.water;$('serviceActions').replaceChildren();for(const action of actions){const b=document.createElement('button');b.textContent=action.label;b.disabled=!!action.disabled;b.onclick=action.run;$('serviceActions').appendChild(b);}$('servicesPanel').classList.remove('hidden');$('closeServices').focus();}
function closeServices(){$('servicesPanel').classList.add('hidden');paused=false;keys.clear();}
function navigateService(p,hint='Walk to the marker and press E.'){activeJob=null;serviceRoute={...p,hint};closeServices();toast(p.name+' marked on your map');}
function openCityDirectory(){if(!started||flightInProgress||sleeping)return;if(interiorState&&!interiorState.shop){toast('Use the exit to reach city transport and shops. Home meals are available in your apartment.');return;}const points=cityPoints();const shop=nearestShop(true);panel('City life & paid work','Visit a shop, take transport, or earn money by completing a shift.',[{label:'Shop · groceries & supplies',run:()=>{if(interiorState?.shop)openShopCounter();else if(shop)navigateService({x:shop.x,z:shop.doorZ,name:shop.name},'Press E at the shop entrance.');}},{label:'Bus station · $'+Math.round(60*(selectedCharacter==='nova'?1.2:1))+' shifts',run:()=>navigateService(points.bus)},{label:'Railway station · $'+Math.round(90*(selectedCharacter==='nova'?1.2:1))+' shifts',run:()=>navigateService(points.rail)},{label:'Airport work · $'+Math.round(120*(selectedCharacter==='nova'?1.2:1))+' shifts',run:()=>navigateService(points.airport)},{label:'Eat snack (+30 energy)',disabled:!cityInventory.snack,run:()=>consumeItem('snack')},{label:'Drink water (+15 energy)',disabled:!cityInventory.water,run:()=>consumeItem('water')}]);}
function nearestShop(any=false){const choices=shopLocations.concat(buildingEntries().filter(b=>!buildings.some(o=>o.x===b.x&&o.z===b.z)).map(b=>({...b,side:-1,doorZ:b.z-b.d/2-.95,name:'City Market'})));let best=null,d=any?Infinity:3;for(const s of choices){const n=Math.hypot(player.pos.x-s.x,player.pos.z-s.doorZ);if(n<d){best=s;d=n;}}return best;}
function enterShop(shop){enterBuilding(shop,{name:shop.name,color:'#8c9c90'});interiorState.kind='shop';interiorState.home=null;interiorState.shop=shop;const keep=interiorRoom.children.slice(0,6);for(const o of [...interiorRoom.children])if(!keep.includes(o)){interiorRoom.remove(o);if(o.isMesh&&o.geometry!==geoBox)o.geometry.dispose();}interiorWalls=interiorWalls.slice(0,4);const add=(w,h,d,x,y,z,m,solid=false)=>{box(w,h,d,x,y,z,m,interiorRoom);if(solid)interiorWalls.push({x,z,w:w/2,d:d/2});};add(9,1.15,1.3,0,.6,-5,mat('#476369'),true);for(const x of [-7,7])for(const z of [-6,0,5]){add(2,2.1,3,x,1.05,z,mat('#92734e'),true);for(let y=.5;y<2;y+=.6)for(let k=0;k<3;k++)add(.45,.4,.45,x+(k-1)*.55,y,z,mat(['#c07a53','#8aa05d','#7395af'][k]));}const cashier=makePerson(characters[2]);cashier.position.set(0,0,-7);cashier.rotation.y=0;humanPose(cashier,0,0);interiorRoom.add(cashier);toast('Welcome · Walk to the counter and press E to shop');}
function openShopCounter(){panel('Market counter','Buy supplies with money earned at transport hubs. Food and water restore energy used during shifts.',[{label:'Buy snack · $12 · restores 30 energy',disabled:cityMoney<12,run:()=>buyItem('snack',12)},{label:'Buy water · $6 · restores 15 energy',disabled:cityMoney<6,run:()=>buyItem('water',6)},{label:'Eat a snack',disabled:!cityInventory.snack,run:()=>consumeItem('snack',true)},{label:'Drink water',disabled:!cityInventory.water,run:()=>consumeItem('water',true)}]);}
function buyItem(item,cost){if(!interiorState?.shop||Math.hypot(player.pos.x,player.pos.z+3.5)>4||cityMoney<cost)return false;cityMoney-=cost;cityInventory[item]++;saveEconomy();openShopCounter();return true;}
function consumeItem(item,shop=false){if(!cityInventory[item])return;cityInventory[item]--;cityEnergy=Math.min(100,cityEnergy+(item==='snack'?30:15));saveEconomy();shop?openShopCounter():openCityDirectory();}
function openStation(p){const pay=Math.round({bus:60,rail:90,airport:120}[p.type]*(selectedCharacter==='nova'?1.2:1));panel(p.name,'You are inside the service area. Buy a ticket or complete three clearly marked tasks to earn $'+pay+'. Each completed shift uses 10 energy.',[{label:'Start '+p.type+' shift · Earn $'+pay,disabled:!!activeJob||cityEnergy<10,run:()=>startJob(p)},...(p.type==='bus'?[{label:'Bus to airport · $5',disabled:cityMoney<5,run:()=>takeTransit(p,'airport',5)}]:p.type==='rail'?[{label:'Train to next destination district · $15',disabled:cityMoney<15,run:()=>takeTransit(p,'rail',15)}]:[])]);}
function startJob(p){if(activeJob||cityEnergy<10||Math.hypot(player.pos.x-p.x,player.pos.z-p.z)>12)return;const tasks=p.type==='airport'?[{x:p.a.x-36,z:36,name:'Collect checked baggage'},{x:p.a.x+36,z:36,name:'Load baggage trolley'},{x:p.x,z:p.z,name:'Report to the supervisor'}]:p.type==='bus'?[{x:p.x-20,z:-248,name:'Inspect bus bay'},{x:p.x+20,z:-248,name:'Check passenger tickets'},{x:p.x,z:p.z,name:'Complete dispatch report'}]:[{x:p.x-25,z:296,name:'Check platform tickets'},{x:p.x+25,z:296,name:'Inspect boarding platform'},{x:p.x,z:p.z,name:'Report to station manager'}];activeJob={type:p.type,tasks,index:0,pay:Math.round({bus:60,rail:90,airport:120}[p.type]*(selectedCharacter==='nova'?1.2:1))};serviceRoute={...tasks[0],hint:'Press E at this task marker · 1 / 3'};closeServices();}
function advanceJob(){if(!activeJob||driving||interiorState)return false;const t=activeJob.tasks[activeJob.index];if(Math.hypot(player.pos.x-t.x,player.pos.z-t.z)>3.2)return false;activeJob.index++;if(activeJob.index===activeJob.tasks.length){const pay=activeJob.pay;activeJob=null;serviceRoute=null;cityMoney+=pay;cityEnergy-=10;saveEconomy();toast('Shift completed · Earned $'+pay);}else{serviceRoute={...activeJob.tasks[activeJob.index],hint:'Press E at this task marker · '+(activeJob.index+1)+' / 3'};toast('Task complete · Next task marked');}return true;}
function takeTransit(p,type,cost){if(cityMoney<cost||Math.hypot(player.pos.x-p.x,player.pos.z-p.z)>12)return;cityMoney-=cost;boardingPass=null;activeJob=null;serviceRoute=null;saveEconomy();closeServices();const a=type==='rail'?airportDestinations[(airportDestinations.indexOf(p.a)+1)%airportDestinations.length]:p.a;player.pos.set(type==='rail'?a.x-120:a.x,.02,type==='rail'?280:16);player.model.position.copy(player.pos);updateWorld(player.pos,true);populateNearbyCrowd();toast(type==='rail'?'Train arrived · '+a.country:'Bus arrived at the airport');}
function bookFlight(a){if(boardingPass?.destination===a.id&&boardingPass.stage==='cleared'){flyTo(a);return;}const origin=nearTerminal();if(!origin)return;boardingPass={destination:a.id,origin:origin.id,stage:'reserved'};closeFlights();navigateService(cityPoints().checkin,'Bring your booking to the check-in counter. Press E.');}
function airportService(p){if(p.type==='checkin'){panel('Airline check-in',boardingPass?'Booking for '+airportDestinations.find(a=>a.id===boardingPass.destination).country+' · Check in your bag and collect a boarding pass.':'Select a destination at Departures first.',[{label:'Check in baggage & collect boarding pass',disabled:!boardingPass||boardingPass.stage!=='reserved',run:()=>{if(Math.hypot(player.pos.x-p.x,player.pos.z-p.z)>5)return;boardingPass.stage='checked-in';navigateService(cityPoints().security,'Walk through the security scanner and press E.');}}]);}else{panel('Airport security','Your boarding pass and baggage must be checked before boarding.',[{label:'Present boarding pass & complete screening',disabled:!boardingPass||boardingPass.stage!=='checked-in',run:()=>{if(Math.hypot(player.pos.x-p.x,player.pos.z-p.z)>5)return;boardingPass.stage='cleared';navigateService({x:p.a.x,z:20,name:'Departure gate'},'Press E and select your booked flight to board.');}}]);}}
function interactService(){if(nearOwnBed()){sleepInBed();return true;}if(advanceJob())return true;if(interiorState){if(interiorState.shop&&Math.hypot(player.pos.x,player.pos.z+3.5)<4){openShopCounter();return true;}return false;}for(const p of Object.values(cityPoints()))if(Math.hypot(player.pos.x-p.x,player.pos.z-p.z)<12){p.type==='checkin'||p.type==='security'?airportService(p):openStation(p);return true;}const shop=nearestShop();if(shop){enterShop(shop);return true;}return false;}
function placePedestrian(p,index,behindPlayer=false){if(p.dead)return false;const viewAngle=player.angle+yaw,viewX=Math.sin(viewAngle),viewZ=Math.cos(viewAngle);for(let n=0;n<160;n++){const road=player.pos.x<600?roadsX[(index+n)%roadsX.length]:Math.round(player.pos.x/60)*60+(index%5-2)*60,x=player.pos.x<-133?-140+p.dir*1.1:road+p.dir*10,offset=behindPlayer?105+(index%8)*7+(n%10)*4:12+(index%10)*10+(n%8)*2,z=player.pos.z+((index+n)%2?1:-1)*offset,dx=x-player.pos.x,dz=z-player.pos.z;if(behindPlayer&&(dx*viewX+dz*viewZ>-30||Math.hypot(dx,dz)<100))continue;if(personClearAt(x,z,PERSON_RADIUS,p)){p.laneX=x;p.wait=0;p.respawnAt=0;p.model.position.set(x,groundHeight(x,z),z);p.model.visible=true;p.model.rotation.set(0,p.dir>0?0:Math.PI,0);return true;}}p.model.visible=false;return false;}
function populateNearbyCrowd(){if(interiorState)return;pedestrians.forEach((p,i)=>placePedestrian(p,i));}
function seatPerson(model,car){const f=carForward(car),right=new THREE.Vector3(f.z,0,-f.x);model.position.copy(car.position).addScaledVector(right,.36).addScaledVector(f,.2);model.position.y-=.3;model.rotation.y=Math.atan2(f.x,f.z);model.visible=true;specialPose(model,'ride',elapsed);}
