 moveInto(homeOptions[0]);check('Exactly selected apartment is owned',ownsCurrentHome());leaveBuilding();const home=homeOptions[0];enterLobby({...home.building,side:1,doorZ:home.building.z+home.building.d/2+1.2});openLift();[...$('serviceActions').children].find(b=>b.textContent.startsWith('Floor 2')).click();await wait(1100);check('Lift arrives at floor 2 with neighbours',interiorState.kind==='hallway'&&interiorState.floor===2&&indoorPeople.length===2);check('Only apartment 201 accepts home key',isOwnApartment(2,0)&&!isOwnApartment(2,1)&&!isOwnApartment(1,0));player.pos.set(0,1000,-6);interact();check('Neighbour door does not open a home',interiorState.kind==='hallway'&&$('serviceTitle').textContent==='Apartment 202');closeServices();player.pos.set(-6,1000,-6);interact();check('Own apartment unlocks from hallway',ownsCurrentHome());
 homeAction('sit');check('Sofa action enters seated state',homeActivity?.type==='sit');await wait(120);check('Sitting pose visible and stationary',player.model.visible&&$('mode').textContent==='SITTING AT HOME');check('Seated hips rest above sofa cushion',Math.abs(player.model.userData.bones.Hips.bone.getWorldPosition(new THREE.Vector3()).y-1001.12)<.02);standUpHome();check('Standing returns to clear floor',!homeActivity&&clearAt(player.pos.x,player.pos.z,.34));cityMoney=100;cityEnergy=15;cityInventory.snack=0;homeAction('eat');check('Home meal deducts price once',cityMoney===92&&homeActivity?.type==='eat');await wait(2800);check('Meal restores energy and finishes',cityEnergy===50&&!homeActivity);await homeAction('sleep');check('Home sleep button works from anywhere',cityEnergy===100&&!sleeping&&$('clock').textContent==='07:00'&&clearAt(player.pos.x,player.pos.z,.34));
 moveInto(homeOptions[1]);check('Moving owns only one apartment',chosenHome.id===homeOptions[1].id);leaveBuilding();enterLobby({...home.building,side:1,doorZ:home.building.z+home.building.d/2+1.2});enterResidentialFloor(2);check('Old home key is revoked',!isOwnApartment(2,0)&&!ownsCurrentHome());leaveBuilding();
