 const a=airportDestinations[0];player.pos.set(a.x,.02,20);updateWorld(player.pos,true);boardingPass={destination:airportDestinations[1].id,origin:a.id,stage:'cleared'};const flying=flyTo(airportDestinations[1]);check('Boarding creates visible flight scene',!!flightScene&&flightInProgress);await flying;check('Flight arrives with city and stations',nearTerminal()===airportDestinations[1]&&cityPoints().rail.a===airportDestinations[1]);
